import{_ as d,l as r,o as e,c as n,v as t,p as s,x as i,d as l,i as w,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"wait-die 与 wound-wait","description":"","frontmatter":{"title":"wait-die 与 wound-wait","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/wait-die.md","filePath":"cs/wait-die.md","lastUpdated":1789023840000}'),p={name:"cs/wait-die.md"};function c(u,a,B,h,_,m){const o=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="wait-die-与-wound-wait" tabindex="-1">wait-die 与 wound-wait <a class="header-anchor" href="#wait-die-与-wound-wait" aria-label="Permalink to &quot;wait-die 与 wound-wait&quot;">​</a></h1><div class="epigraph"><p>用事务时间戳决定谁等谁死：wait-die 让老的等、年轻的死；wound-wait 让老的伤年轻的。环因此长不出来。</p><footer>—— 据 Rosenkrantz, Stearns and Lewis；Gray and Reuter；对照 Coffman 四条件</footer></div><p><a href="/cs/db-deadlock">上一课</a>用等待图检测环并牺牲一人。本课不重画检测。缺口是预防：不让环形成。时间戳方法在分布式里尤其有用——等图难以及时收集。两阶段提交下一课处理的是另一维度：多资源管理器的原子提交，不是同一库内锁环。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>库内死锁课留下「检测并回滚」。预防可以破占有并等待：预先声明锁集（难）。或给事务全序：wait-die——年轻事务请求老事务持有的锁则中止（die），老的可以等年轻的；wound-wait——老的请求时让年轻的中止（wound），年轻的等老的。缺口是<strong>用时间戳打破对称</strong>，避免等待图。</p><p><span class="marginnote">被中止的事务应带着原时间戳重启，否则可能饥饿。这与 OS 死锁预防的银行家算法对象不同：这里牺牲的是事务，不是拒绝分配内存。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>开始时分配 TS。锁冲突时比较 TS，按选定算法 wait 或 abort。检测法仍可用于单机低开销；预防法在锁持有时间长、通信贵时有意义。本课不把超时当严谨算法——超时是工程近似。</p>',8)),(e(),s(E,null,{default:i(()=>[w(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%E5%B7%B2%E8%A2%AB%E6%8C%81%E6%9C%89%E7%9A%84%E9%94%81%22%5D%20--%3E%20WD%5B%22wait-die%3A%20%E5%B9%B4%E8%BD%BB%E5%88%99%E6%AD%BB%22%5D%0A%20%20REQ%20--%3E%20WW%5B%22wound-wait%3A%20%E5%B9%B4%E8%BD%BB%E5%88%99%E8%A2%AB%E4%BC%A4%22%5D%0A%20%20WD%20--%3E%20NORING%5B%22%E7%AD%89%E5%BE%85%E8%BE%B9%E6%B2%BF%E6%97%B6%E9%97%B4%E6%88%B3%E5%8D%95%E5%90%91%22%5D%0A%20%20WW%20--%3E%20NORING%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>两种算法都让等待关系与 TS 同向，图无环。代价是可能误杀（本没有环也中止）。重启重做工作，与 ARIES UNDO/REDO 兼容。后课 2PC 的阻塞是协调器故障，不是锁环，不要混。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入死锁概率模型当必算。跨库一次提交如何投票，下一课两阶段提交。</p><p>后课默认：单库锁环可用检测或时间戳预防。多资源原子性是 2PC。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>wait-die / wound-wait 用 TS 预防锁环。</li><li>中止后保持 TS 以防饥饿。</li><li>分布式原子提交下一课。</li><li>出处：Rosenkrantz et al.；Gray and Reuter。</li></ul>',7))])}const T=d(p,[["render",c]]);export{f as __pageData,T as default};
